import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Pipeline.
 *
 * @stability experimental
 */
export interface IPipelineRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Pipeline resource.
     */
    readonly pipelineRef: PipelineReference;
}
/**
 * A reference to a Pipeline resource.
 *
 * @struct
 * @stability external
 */
export interface PipelineReference {
    /**
     * The PipelineArn of the Pipeline resource.
     */
    readonly pipelineArn: string;
}
/**
 * Indicates that this resource can be referenced as a PipelineBlueprint.
 *
 * @stability experimental
 */
export interface IPipelineBlueprintRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a PipelineBlueprint resource.
     */
    readonly pipelineBlueprintRef: PipelineBlueprintReference;
}
/**
 * A reference to a PipelineBlueprint resource.
 *
 * @struct
 * @stability external
 */
export interface PipelineBlueprintReference {
    /**
     * The Arn of the PipelineBlueprint resource.
     */
    readonly pipelineBlueprintArn: string;
}
